package com.example.discovery.consumer.service;import static org.assertj.core.api.Assertions.*;import com.example.discovery.consumer.model.ServiceInstance;import java.util.*;import java.util.concurrent.*;import org.junit.jupiter.api.Test;class RoundRobinLoadBalancerTest{List<ServiceInstance> instances(){return List.of(new ServiceInstance("payment-service","p-1","localhost",8081,"",null,null,"UP"),new ServiceInstance("payment-service","p-2","localhost",8082,"",null,null,"UP"),new ServiceInstance("payment-service","p-3","localhost",8083,"",null,null,"UP"));}@Test void rotatesUsingRoundRobin(){var lb=new RoundRobinLoadBalancer();assertThat(lb.orderedCandidates("payment-service",instances()).getFirst().port()).isEqualTo(8081);assertThat(lb.orderedCandidates("payment-service",instances()).getFirst().port()).isEqualTo(8082);assertThat(lb.orderedCandidates("payment-service",instances()).getFirst().port()).isEqualTo(8083);assertThat(lb.orderedCandidates("payment-service",instances()).getFirst().port()).isEqualTo(8081);}@Test void isThreadSafe()throws Exception{var lb=new RoundRobinLoadBalancer();try(var ex=Executors.newFixedThreadPool(8)){var tasks=new ArrayList<Callable<Integer>>();for(int i=0;i<100;i++)tasks.add(()->lb.orderedCandidates("payment-service",instances()).getFirst().port());var results=ex.invokeAll(tasks);assertThat(results).hasSize(100);}}}
